(()=>{let e=[{id:1,name:"Nguyễn Văn A",dob:"2000-05-10",gender:"Nam"},{id:2,name:"Trần Thị B",dob:"2001-08-22",gender:"Nữ"}];function t(){const n=document.getElementById("studentTableBody");n&&(n.innerHTML="",e.forEach(e=>{const t=document.createElement("tr");t.innerHTML=`\n      <td>${e.id}</td>\n      <td><b>${e.name}</b></td>\n      <td>${e.dob}</td>\n      <td>${e.gender}</td>\n      <td><button class="btn-delete" data-id="${e.id}">Xóa</button></td>\n    `,n.appendChild(t)}),document.querySelectorAll(".btn-delete").forEach(n=>{n.addEventListener("click",n=>{var d;d=parseInt(n.target.getAttribute("data-id"),10),e=e.filter(e=>e.id!==d),t()})}))}document.addEventListener("DOMContentLoaded",()=>{t();const n=document.getElementById("studentForm");n&&n.addEventListener("submit",d=>{d.preventDefault();const a=document.getElementById("nameInput").value.trim(),o=document.getElementById("dobInput").value,r=document.getElementById("genderInput").value;a&&o&&r&&(function(n,d,a){const o={id:e.length>0?Math.max(...e.map(e=>e.id))+1:1,name:n,dob:d,gender:a};e.push(o),t()}(a,o,r),n.reset())})})})();